// purgeExpired drops entries whose ttl has passed.
func (c *tokenCache) purgeExpired() {
	c.mu.Lock()
	defer c.mu.Unlock()
	for k, it := range c.items {
		if it.expired() {
			delete(c.items, k)
		}
	}
}

